BEGIN;

CREATE TABLE IF NOT EXISTS "tblStudy" (
    "CENTRALStudyID" integer, "CRGStudyID" integer PRIMARY KEY,
    "ShortName" text NOT NULL UNIQUE, "StatusofStudy" text NOT NULL,
    "TrialistContactDetails" text, "CENTRALSubmissionStatus" text, "Notes" text,
    "DateEntered" text NOT NULL, "DateEdited" text, "DateToCENTRAL" text,
    "Search_Tagged" integer, "NumberParticipants" text, "Countries" text,
    "Duration" text, "UDef4" text, "Comparison" text, "ISRCTN" text,
    "UDef6" text, "TrialRegistrationID" text
);

CREATE TABLE IF NOT EXISTS "tblReport" (
    "CENTRALReportID" integer, "CRGReportID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ReportNumber" integer NOT NULL DEFAULT -1, "Title" text NOT NULL,
    "Notes" text, "OriginalTitle" text, "Authors" text NOT NULL,
    "Journal" text, "Year" integer NOT NULL, "Volume" text,
    "Issue" text, "Pages" text, "Language" text, "Abstract" text,
    "CENTRALSubmissionStatus" integer, "CopyStatus" text, "DatetoCENTRAL" text,
    "Dateentered" text NOT NULL, "DateEdited" text, "Editors" text,
    "Publisher" text, "City" text, "DupString" text, "TypeofReportID" integer,
    "PublicationTypeID" integer NOT NULL, "Edition" text, "Medium" text,
    "StudyDesign" text, "DOI" text, "UDef3" text, "ISBN" text, "UDef5" text,
    "PMID" text, "TrialRegistrationID" text, "UDef9" double precision,
    "UDef10" double precision, "UDef8" double precision
);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'tblReport'
          AND column_name = 'CRGReportID'
          AND is_identity = 'YES'
    ) AND NOT EXISTS (
        SELECT 1
        FROM pg_attrdef definition
        JOIN pg_class relation ON relation.oid = definition.adrelid
        JOIN pg_attribute column_definition
          ON column_definition.attrelid = relation.oid
         AND column_definition.attnum = definition.adnum
        WHERE relation.relname = 'tblReport'
          AND column_definition.attname = 'CRGReportID'
    ) THEN
        ALTER TABLE "tblReport"
            ALTER COLUMN "CRGReportID" ADD GENERATED BY DEFAULT AS IDENTITY;
    END IF;
END
$$;

ALTER TABLE "tblReport" ALTER COLUMN "Journal" DROP NOT NULL;

CREATE TABLE IF NOT EXISTS "tblIntervention" ("InterventionID" integer PRIMARY KEY, "InterventionDescription" text);
CREATE TABLE IF NOT EXISTS "tblHealthCareCondition" ("HealthCareConditionID" integer PRIMARY KEY, "HealthCareConditionDescription" text);
CREATE TABLE IF NOT EXISTS "tblOutcome" ("OutcomeID" integer PRIMARY KEY, "OutcomeDescription" text);
CREATE TABLE IF NOT EXISTS "tblDesign" ("DesignID" integer PRIMARY KEY, "DesignDescription" text);
CREATE TABLE IF NOT EXISTS "tblParticipant" ("ParticipantsID" integer PRIMARY KEY, "ParticipantDescription" text NOT NULL);

CREATE TABLE IF NOT EXISTS "tblStudyReport" (
    "StudyReportID" integer PRIMARY KEY,
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "CRGReportID" integer NOT NULL REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    UNIQUE ("CRGReportID", "CRGStudyID")
);
CREATE TABLE IF NOT EXISTS "tblStudyAdded" (
    "CRGStudyID" integer PRIMARY KEY REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "DateCreated" timestamp, "CreatedBy" text
);
CREATE TABLE IF NOT EXISTS "tblStudyReportAdded" (
    "StudyReportID" integer NOT NULL REFERENCES "tblStudyReport" ("StudyReportID") ON DELETE CASCADE,
    "DateCreated" timestamp, "CreatedBy" text NOT NULL,
    "Confirmed" boolean NOT NULL DEFAULT false,
    PRIMARY KEY ("StudyReportID", "CreatedBy")
);
CREATE TABLE IF NOT EXISTS "tblStudyIntervention" (
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "InterventionID" integer NOT NULL REFERENCES "tblIntervention" ("InterventionID") ON DELETE CASCADE,
    PRIMARY KEY ("CRGStudyID", "InterventionID")
);
CREATE TABLE IF NOT EXISTS "tblStudyHealthCareCondition" (
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "HealthCareConditionID" integer NOT NULL REFERENCES "tblHealthCareCondition" ("HealthCareConditionID") ON DELETE CASCADE,
    PRIMARY KEY ("CRGStudyID", "HealthCareConditionID")
);
CREATE TABLE IF NOT EXISTS "tblStudyOutcome" (
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "OutcomeID" integer NOT NULL REFERENCES "tblOutcome" ("OutcomeID") ON DELETE CASCADE,
    PRIMARY KEY ("CRGStudyID", "OutcomeID")
);
CREATE TABLE IF NOT EXISTS "tblStudyDesign" (
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "DesignID" integer NOT NULL REFERENCES "tblDesign" ("DesignID") ON DELETE CASCADE,
    PRIMARY KEY ("CRGStudyID", "DesignID")
);
CREATE TABLE IF NOT EXISTS "tblStudyParticipant" (
    "CRGStudyID" integer NOT NULL REFERENCES "tblStudy" ("CRGStudyID") ON DELETE CASCADE,
    "ParticipantsID" integer NOT NULL REFERENCES "tblParticipant" ("ParticipantsID") ON DELETE CASCADE,
    PRIMARY KEY ("CRGStudyID", "ParticipantsID")
);

CREATE TABLE IF NOT EXISTS "tblBatch" (
    "BatchHash" text PRIMARY KEY,
    "BatchDescription" text NOT NULL,
    "DateCreated" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UploadedBy" text
);
CREATE TABLE IF NOT EXISTS "tblBatchAssignees" (
    "BatchHash" text NOT NULL REFERENCES "tblBatch" ("BatchHash") ON DELETE CASCADE,
    "Assignee" text NOT NULL,
    PRIMARY KEY ("BatchHash", "Assignee")
);
CREATE INDEX IF NOT EXISTS "idx_batchassignees_assignee"
    ON "tblBatchAssignees" ("Assignee");
CREATE TABLE IF NOT EXISTS "tblFulltextExtractions" (
    "CRGReportID" integer PRIMARY KEY REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    "data" jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS "tblReportAdded" (
    "CRGReportID" integer PRIMARY KEY REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    "BatchHash" text NOT NULL REFERENCES "tblBatch" ("BatchHash") ON DELETE CASCADE,
    "AutoSearchedPdf" boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS "idx_reportadded_batch_report"
    ON "tblReportAdded" ("BatchHash", "CRGReportID");
CREATE TABLE IF NOT EXISTS "tblBatchInnerScore" (
    "CRGReportID" integer NOT NULL REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    "OtherID" integer NOT NULL REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    "Score" double precision NOT NULL,
    PRIMARY KEY ("CRGReportID", "OtherID")
);
CREATE INDEX IF NOT EXISTS "idx_batchinnerscore_report_score"
    ON "tblBatchInnerScore" ("CRGReportID", "Score");
CREATE INDEX IF NOT EXISTS "idx_batchinnerscore_other_score"
    ON "tblBatchInnerScore" ("OtherID", "Score");
CREATE TABLE IF NOT EXISTS "tblReportFlag" (
    "CRGReportID" integer NOT NULL REFERENCES "tblReport" ("CRGReportID") ON DELETE CASCADE,
    "CreatedBy" text NOT NULL,
    "DateCreated" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "Message" text NOT NULL,
    "Public" boolean NOT NULL DEFAULT false,
    PRIMARY KEY ("CRGReportID", "CreatedBy")
);
CREATE INDEX IF NOT EXISTS "idx_reportflag_created_by"
    ON "tblReportFlag" ("CreatedBy");
CREATE TABLE IF NOT EXISTS "tblEvent" (
    "EventID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DateCreated" timestamp NOT NULL,
    "CreatedBy" text NOT NULL,
    "Type" text NOT NULL,
    "RelatedReport" integer REFERENCES "tblReport" ("CRGReportID") ON DELETE SET NULL
);

