INSERT INTO "tblReport" ("CENTRALReportID", "CRGReportID", "ReportNumber", "Title", "Authors", "Journal", "Year", "Abstract", "Dateentered", "DateEdited", "TypeofReportID", "PublicationTypeID", "StudyDesign", "DOI", "TrialRegistrationID", "OriginalTitle", "Language", "Publisher") VALUES

(NULL, '2000001', '1', 'Baseline characteristics of adults enrolled in an evaluation of home blood pressure monitoring: evidence from participating centres', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'BMJ Open', '2024', 'This baseline report describes 117 adults enrolled to assess home blood pressure monitoring for hypertension. Participants were recruited within a pragmatic network of hospital and community providers; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The analysis also considered differences between hospital and community delivery settings.', '2025-01-25 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0001', 'SYNTH-ISRCTN-0000001', 'Baseline characteristics of adults enrolled in an evaluation of home blood pressure monitoring', 'English', 'Medidex Synthetic Press'),
(NULL, '2000002', '2', 'Comparative effectiveness of home blood pressure monitoring for hypertension: a pragmatic service evaluation', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'Journal of Clinical Epidemiology', '2025', 'A multicentre investigation examined home blood pressure monitoring against standard care in 117 adults with hypertension. The intervention showed a small but measurable benefit for glycaemic control, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-02-13 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0002', 'SYNTH-ISRCTN-0000001', 'Comparative effectiveness of home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000003', '3', 'Healthcare utilization duringhome blood pressure monitoring for hypertension: findings from routine clinical practice', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'The Lancet Regional Health', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home blood pressure monitoring for hypertension. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Cost estimates were presented from the healthcare-system perspective and in sensitivity analyses from a wider societal perspective.', '2025-01-13 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0003', 'SYNTH-ISRCTN-0000001', 'Health-service costs associated with home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000004', '4', 'Longer-term outcomes following home blood pressure monitoring in hypertension: a longitudinal cohort analysis', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'BMC Health Services Research', '2026', 'This follow-up examined participants with hypertension after the initial evaluation of home blood pressure monitoring. At six to twelve months, the direction of change in glycaemic control was assessed alongside treatment persistence, healthcare use, and late adverse events. The analysis suggests durable benefit for some participants but remains vulnerable to loss to follow-up. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-02-02 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0004', 'SYNTH-ISRCTN-0000001', 'Longer-term outcomes following home blood pressure monitoring in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000005', '5', 'Baseline characteristics of adults enrolled in an evaluation of home pulmonary rehabilitation: a participant-level secondary analysis', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'Journal of Clinical Epidemiology', '2025', 'This baseline report describes 154 adults enrolled to assess home pulmonary rehabilitation for chronic obstructive pulmonary disease. Participants were recruited using electronic records and clinician referral; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-02-21 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0005', 'SYNTH-ISRCTN-0000002', 'Baseline characteristics of adults enrolled in an evaluation of home pulmonary rehabilitation', 'English', 'Medidex Synthetic Press'),
(NULL, '2000006', '6', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease: a community-based assessment', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'The Lancet Regional Health', '2024', 'Investigators explored home pulmonary rehabilitation against standard care in 154 adults with chronic obstructive pulmonary disease. The observed difference was clinically interpretable for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-01-21 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0006', 'SYNTH-ISRCTN-0000002', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000007', '7', 'Budget impact ofhome pulmonary rehabilitation for chronic obstructive pulmonary disease: a patient-centred outcomes report', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'BMC Health Services Research', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home pulmonary rehabilitation for chronic obstructive pulmonary disease. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Costs were separated into intervention delivery, primary care, hospital care, and medication use.', '2025-02-09 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0007', 'SYNTH-ISRCTN-0000002', 'Health-service costs associated with home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000008', '8', 'Secondary analysis of exercise tolerance after home pulmonary rehabilitation for chronic obstructive pulmonary disease: results from linked clinical records', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'Trials', '2025', 'A prespecified secondary analysis examined variation in exercise tolerance after home pulmonary rehabilitation among adults with chronic obstructive pulmonary disease. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-10 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0008', 'SYNTH-ISRCTN-0000002', 'Secondary analysis of exercise tolerance after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000009', '9', 'Registered Protocol For The Planned Evaluation for a graded activity programme in chronic low back pain: a mixed-methods implementation report', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2022', 'researchers evaluated a graded activity programme for adults with chronic low back pain. Participants will be recruited at urban and regional clinical sites; the planned sample is 191 and pain-related function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-01-29 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0009', 'SYNTH-ISRCTN-0000003', 'Registered Protocol For The Planned Evaluation for a graded activity programme in chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000010', '10', 'Comparative effectiveness of a graded activity programme for chronic low back pain: a multisite effectiveness study', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2025', 'A multicentre investigation examined a graded activity programme against standard care in 191 adults with chronic low back pain. The intervention showed a small but measurable benefit for pain-related function, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-02-17 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0010', 'SYNTH-ISRCTN-0000003', 'Comparative effectiveness of a graded activity programme for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000011', '11', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction: a prespecified analysis of outcomes', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'BMC Health Services Research', '2025', 'An outpatient research network tested structured medication review against standard care in 228 adults with heart failure with preserved ejection fraction. The observed difference was clinically interpretable for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Differences in adherence were more pronounced among participants recruited through community services.', '2025-01-18 09:00:00', '2026-05-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0011', 'SYNTH-ISRCTN-0000004', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000012', '12', 'Methods Paper Describing The Trial Framework for guided behavioural activation in major depressive disorder: a health-system perspective', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Trials', '2024', 'researchers evaluated guided behavioural activation for adults with major depressive disorder. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 265 and depressive symptom severity is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-02-06 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0012', 'SYNTH-ISRCTN-0000005', 'Methods Paper Describing The Trial Framework for guided behavioural activation in major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000013', '13', 'A pragmatic evaluation of guided behavioural activation for major depressive disorder: a follow-up analysis of care pathways', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMJ Open', '2025', 'The trial team compared guided behavioural activation against standard care in 265 adults with major depressive disorder. Between-group estimates favoured the intervention for depressive symptom severity, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The study team documented variation in delivery intensity across participating sites.', '2025-01-07 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0013', 'SYNTH-ISRCTN-0000005', 'A pragmatic evaluation of guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000014', '14', 'Who benefits from guided behavioural activation? A subgroup analysis in major depressive disorder: an outpatient outcomes study', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Journal of Clinical Epidemiology', '2025', 'This analysis explored heterogeneity of response to guided behavioural activation in adults with major depressive disorder. Improvement in depressive symptom severity was observed across several prespecified strata, with the largest estimates among participants with greater baseline impairment. The findings are exploratory and require confirmation in independent cohorts. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-01-26 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0014', 'SYNTH-ISRCTN-0000005', 'Who benefits from guided behavioural activation? A subgroup analysis in major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000016', '16', 'Protocol And Statistical Analysis Plan for home strength and balance exercise in postoperative joint replacement recovery: an analysis of treatment persistence', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMJ Open', '2025', 'a multicentre investigation examined home strength and balance exercise for adults with postoperative joint replacement recovery. Participants will be recruited across community services and outpatient practices; the planned sample is 302 and functional mobility is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-01-15 09:00:00', '2026-07-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0016', 'SYNTH-ISRCTN-0000006', 'Protocol And Statistical Analysis Plan for home strength and balance exercise in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000017', '17', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery: a report from regional services', 'Arjun Mehta//Grace Kim//Peter Osei', 'Journal of Clinical Epidemiology', '2024', 'Researchers evaluated home strength and balance exercise against standard care in 302 adults with postoperative joint replacement recovery. The intervention showed a small but measurable benefit for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The analysis also considered differences between hospital and community delivery settings.', '2025-02-03 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0017', 'SYNTH-ISRCTN-0000006', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000018', '18', 'Economic outcomes followinghome strength and balance exercise for postoperative joint replacement recovery: a clinical epidemiology analysis', 'Arjun Mehta//Grace Kim//Peter Osei', 'The Lancet Regional Health', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. The analysis reported both observed trial costs and projected costs over a longer decision horizon.', '2025-02-22 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0018', 'SYNTH-ISRCTN-0000006', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000019', '19', 'Healthcare utilization duringhome strength and balance exercise for postoperative joint replacement recovery: an assessment of variation in response', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMC Health Services Research', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Costs were separated into intervention delivery, primary care, hospital care, and medication use.', '2025-01-22 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0019', 'SYNTH-ISRCTN-0000006', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000020', '20', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery: a service-user experience report', 'Arjun Mehta//Grace Kim//Peter Osei', 'Trials', '2025', 'This analysis explored heterogeneity of response to home strength and balance exercise in adults with postoperative joint replacement recovery. Improvement in functional mobility was observed across several prespecified strata, with the largest estimates among participants with greater baseline impairment. The findings are exploratory and require confirmation in independent cohorts. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-02-11 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0020', 'SYNTH-ISRCTN-0000006', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000021', '21', 'Cost and resource implications ofhome strength and balance exercise for postoperative joint replacement recovery: a longitudinal safety analysis', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMJ Open', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Cost estimates were presented from the healthcare-system perspective and in sensitivity analyses from a wider societal perspective.', '2025-01-11 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0021', 'SYNTH-ISRCTN-0000006', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000022', '22', 'Health-system costs forhome strength and balance exercise for postoperative joint replacement recovery: a study of implementation fidelity', 'Arjun Mehta//Grace Kim//Peter Osei', 'Journal of Clinical Epidemiology', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. The largest contribution to total cost came from follow-up contacts rather than the intervention materials.', '2025-01-30 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0022', 'SYNTH-ISRCTN-0000006', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000023', '23', 'Budget impact ofhome strength and balance exercise for postoperative joint replacement recovery: a comparison across recruitment settings', 'Arjun Mehta//Grace Kim//Peter Osei', 'The Lancet Regional Health', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Results depended most strongly on the assumed rate of continued service use after the study period.', '2025-02-18 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0023', 'SYNTH-ISRCTN-0000006', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000024', '24', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery: an analysis of resource use', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMC Health Services Research', '2025', 'The trial team compared home strength and balance exercise against standard care in 302 adults with postoperative joint replacement recovery. The primary analysis indicated a modest improvement for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-19 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0024', 'SYNTH-ISRCTN-0000006', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000025', '25', 'Longer-term outcomes following home strength and balance exercise in postoperative joint replacement recovery: a report on treatment acceptability', 'Arjun Mehta//Grace Kim//Peter Osei', 'Trials', '2026', 'This follow-up examined participants with postoperative joint replacement recovery after the initial evaluation of home strength and balance exercise. At six to twelve months, the direction of change in functional mobility was assessed alongside treatment persistence, healthcare use, and late adverse events. The analysis suggests durable benefit for some participants but remains vulnerable to loss to follow-up. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-02-07 09:00:00', '2026-07-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0025', 'SYNTH-ISRCTN-0000006', 'Longer-term outcomes following home strength and balance exercise in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000026', '26', 'Baseline characteristics of adults enrolled in an evaluation of personalised dietary counselling: a pragmatic registry analysis', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'Journal of Clinical Epidemiology', '2024', 'This baseline report describes 339 adults enrolled to assess personalised dietary counselling for hypertension. Participants were recruited using electronic records and clinician referral; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-08 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0026', 'SYNTH-ISRCTN-0000007', 'Baseline characteristics of adults enrolled in an evaluation of personalised dietary counselling', 'English', 'Medidex Synthetic Press'),
(NULL, '2000027', '27', 'Clinical outcomes after personalised dietary counselling for hypertension: a study of care access and outcomes', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'The Lancet Regional Health', '2025', 'A multicentre investigation examined personalised dietary counselling against standard care in 339 adults with hypertension. The observed difference was clinically interpretable for systolic blood pressure, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Differences in adherence were more pronounced among participants recruited through community services.', '2025-01-27 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0027', 'SYNTH-ISRCTN-0000007', 'Clinical outcomes after personalised dietary counselling for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000028', '28', 'Implementing personalised dietary counselling in routine care for hypertension: an analysis of longer-term use', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'BMC Health Services Research', '2025', 'This implementation report describes delivery of personalised dietary counselling for people with hypertension across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside systolic blood pressure. Adoption was feasible, although local staffing and infrastructure shaped delivery. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-02-15 09:00:00', '2026-08-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0028', 'SYNTH-ISRCTN-0000007', 'Implementing personalised dietary counselling in routine care for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000029', '29', 'Cost and resource implications ofpersonalised dietary counselling for hypertension: a report on clinical decision-making', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'Trials', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with personalised dietary counselling for hypertension. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Results depended most strongly on the assumed rate of continued service use after the study period.', '2025-01-16 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0029', 'SYNTH-ISRCTN-0000007', 'Health-service costs associated with personalised dietary counselling for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000030', '30', 'Correction: Personalised Dietary Counselling and systolic blood pressure in hypertension: a multisite patient follow-up', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'BMJ Open', '2026', 'This notice corrects a nonclinical metadata error in an earlier report on personalised dietary counselling for hypertension. The participant population, intervention, comparator, analyses, and clinical conclusions are unchanged. The corrected record clarifies the outcome definition and preserves the original study context for evidence review. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-02-04 09:00:00', '2026-08-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0030', 'SYNTH-ISRCTN-0000007', 'Correction: Personalised Dietary Counselling and systolic blood pressure in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000031', '31', 'Baseline characteristics of adults enrolled in an evaluation of brief sleep restriction therapy: evidence from participating centres', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'The Lancet Regional Health', '2025', 'This baseline report describes 376 adults enrolled to assess brief sleep restriction therapy for insomnia in older adults. Participants were recruited through primary-care and specialist clinics; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-02-23 09:00:00', '2026-01-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0031', 'SYNTH-ISRCTN-0000008', 'Baseline characteristics of adults enrolled in an evaluation of brief sleep restriction therapy', 'English', 'Medidex Synthetic Press'),
(NULL, '2000032', '32', 'A pragmatic evaluation of brief sleep restriction therapy for insomnia in older adults: a pragmatic service evaluation', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'BMC Health Services Research', '2024', 'Investigators explored brief sleep restriction therapy against standard care in 376 adults with insomnia in older adults. The observed difference was clinically interpretable for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-01-24 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0032', 'SYNTH-ISRCTN-0000008', 'A pragmatic evaluation of brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000033', '33', 'Correction: Brief Sleep Restriction Therapy and sleep efficiency in insomnia in older adults: findings from routine clinical practice', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'Trials', '2026', 'This notice corrects a nonclinical metadata error in an earlier report on brief sleep restriction therapy for insomnia in older adults. The participant population, intervention, comparator, analyses, and clinical conclusions are unchanged. The corrected record clarifies the outcome definition and preserves the original study context for evidence review. The analysis also considered differences between hospital and community delivery settings.', '2025-02-12 09:00:00', '2026-01-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0033', 'SYNTH-ISRCTN-0000008', 'Correction: Brief Sleep Restriction Therapy and sleep efficiency in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000034', '34', 'Prospective Study Protocol for pacing and energy conservation coaching in post-viral fatigue syndrome: a longitudinal cohort analysis', 'Amara Williams//Diego Alvarez//Ines Pereira', 'BMC Health Services Research', '2024', 'researchers evaluated pacing and energy conservation coaching for adults with post-viral fatigue syndrome. Participants will be recruited at urban and regional clinical sites; the planned sample is 413 and physical function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-12 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0034', 'SYNTH-ISRCTN-0000009', 'Prospective Study Protocol for pacing and energy conservation coaching in post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000035', '35', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome: a participant-level secondary analysis', 'Amara Williams//Diego Alvarez//Ines Pereira', 'Trials', '2025', 'Researchers evaluated pacing and energy conservation coaching against standard care in 413 adults with post-viral fatigue syndrome. Results were consistent with the prespecified hypothesis for physical function, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-02-01 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0035', 'SYNTH-ISRCTN-0000009', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000036', '36', 'Secondary analysis of physical function after pacing and energy conservation coaching for post-viral fatigue syndrome: a community-based assessment', 'Amara Williams//Diego Alvarez//Ines Pereira', 'BMJ Open', '2026', 'A prespecified secondary analysis examined variation in physical function after pacing and energy conservation coaching among adults with post-viral fatigue syndrome. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-02-20 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0036', 'SYNTH-ISRCTN-0000009', 'Secondary analysis of physical function after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000037', '37', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension: a patient-centred outcomes report', 'Noor Rahman//Ethan Cole//Maya Singh', 'Trials', '2025', 'investigators explored home blood pressure monitoring for adults with hypertension. Participants will be recruited using electronic records and clinician referral; the planned sample is 450 and glycaemic control is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-20 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0037', 'SYNTH-ISRCTN-0000010', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000038', '38', 'A pragmatic evaluation of home blood pressure monitoring for hypertension: results from linked clinical records', 'Noor Rahman//Ethan Cole//Maya Singh', 'BMJ Open', '2024', 'An outpatient research network tested home blood pressure monitoring against standard care in 450 adults with hypertension. Results were consistent with the prespecified hypothesis for glycaemic control, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-02-08 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0038', 'SYNTH-ISRCTN-0000010', 'A pragmatic evaluation of home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000039', '39', 'Methods Paper Describing The Trial Framework for home pulmonary rehabilitation in chronic obstructive pulmonary disease: a mixed-methods implementation report', 'Aisha Grant//Victor Petrov//Clara Martin', 'BMJ Open', '2022', 'an outpatient research network tested home pulmonary rehabilitation for adults with chronic obstructive pulmonary disease. Participants will be recruited through primary-care and specialist clinics; the planned sample is 487 and exercise tolerance is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. Service capacity and local referral practices influenced the observed pattern of care.', '2025-01-09 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0039', 'SYNTH-ISRCTN-0000011', 'Methods Paper Describing The Trial Framework for home pulmonary rehabilitation in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000040', '40', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease: a multisite effectiveness study', 'Aisha Grant//Victor Petrov//Clara Martin', 'Journal of Clinical Epidemiology', '2025', 'Investigators explored home pulmonary rehabilitation against standard care in 487 adults with chronic obstructive pulmonary disease. Results were consistent with the prespecified hypothesis for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-28 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0040', 'SYNTH-ISRCTN-0000011', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000041', '41', 'Implementing a graded activity programme in routine care for chronic low back pain: a prespecified analysis of outcomes', 'Amina Okafor//Luis Martinez//Priya Nair', 'Journal of Clinical Epidemiology', '2025', 'This implementation report describes delivery of a graded activity programme for people with chronic low back pain across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside pain-related function. Adoption was feasible, although local staffing and infrastructure shaped delivery. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-02-16 09:00:00', '2026-05-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0041', 'SYNTH-ISRCTN-0000012', 'Implementing a graded activity programme in routine care for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000042', '42', 'Registered Protocol For The Planned Evaluation for structured medication review in heart failure with preserved ejection fraction: a health-system perspective', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'The Lancet Regional Health', '2024', 'researchers evaluated structured medication review for adults with heart failure with preserved ejection fraction. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 141 and symptom burden is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-17 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0042', 'SYNTH-ISRCTN-0000013', 'Registered Protocol For The Planned Evaluation for structured medication review in heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000043', '43', 'Comparative effectiveness of structured medication review for heart failure with preserved ejection fraction: a follow-up analysis of care pathways', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'BMC Health Services Research', '2025', 'The trial team compared structured medication review against standard care in 141 adults with heart failure with preserved ejection fraction. Results were consistent with the prespecified hypothesis for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-05 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0043', 'SYNTH-ISRCTN-0000013', 'Comparative effectiveness of structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000044', '44', 'Cost-effectiveness ofstructured medication review for heart failure with preserved ejection fraction: an outpatient outcomes study', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'Trials', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with structured medication review for heart failure with preserved ejection fraction. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. The economic model varied staff time, service intensity, and the assumed duration of treatment benefit.', '2025-01-06 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0044', 'SYNTH-ISRCTN-0000013', 'Health-service costs associated with structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000045', '45', 'Adverse events and treatment exposure during structured medication review for heart failure with preserved ejection fraction: a real-world assessment of delivery', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'BMJ Open', '2026', 'Safety data from the evaluation of structured medication review for heart failure with preserved ejection fraction were reviewed across 141 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The study team documented variation in delivery intensity across participating sites.', '2025-01-25 09:00:00', '2026-06-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0045', 'SYNTH-ISRCTN-0000013', 'Adverse events and treatment exposure during structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000046', '46', 'Implementing guided behavioural activation in routine care for major depressive disorder: an analysis of treatment persistence', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'BMC Health Services Research', '2025', 'This implementation report describes delivery of guided behavioural activation for people with major depressive disorder across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside depressive symptom severity. Adoption was feasible, although local staffing and infrastructure shaped delivery. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-02-13 09:00:00', '2026-07-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0046', 'SYNTH-ISRCTN-0000014', 'Implementing guided behavioural activation in routine care for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000047', '47', 'Baseline characteristics of adults enrolled in an evaluation of home strength and balance exercise: a report from regional services', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Trials', '2023', 'This baseline report describes 215 adults enrolled to assess home strength and balance exercise for postoperative joint replacement recovery. Participants were recruited across community services and outpatient practices; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-01-14 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0047', 'SYNTH-ISRCTN-0000015', 'Baseline characteristics of adults enrolled in an evaluation of home strength and balance exercise', 'English', 'Medidex Synthetic Press'),
(NULL, '2000048', '48', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery: a clinical epidemiology analysis', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMJ Open', '2025', 'Researchers evaluated home strength and balance exercise against standard care in 215 adults with postoperative joint replacement recovery. The observed difference was clinically interpretable for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-02-02 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0048', 'SYNTH-ISRCTN-0000015', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000049', '49', 'Patient-reported experience after home strength and balance exercise for postoperative joint replacement recovery: an assessment of variation in response', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Journal of Clinical Epidemiology', '2025', 'This report examined patient-reported experience and quality of life after home strength and balance exercise for postoperative joint replacement recovery. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in functional mobility were accompanied by variable satisfaction with access and treatment workload. The analysis also considered differences between hospital and community delivery settings.', '2025-02-21 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0049', 'SYNTH-ISRCTN-0000015', 'Patient-reported experience after home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000050', '50', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery: a service-user experience report, report 50', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2025', 'This analysis explored heterogeneity of response to home strength and balance exercise in adults with postoperative joint replacement recovery. Improvement in functional mobility was observed across several prespecified strata, with the largest estimates among participants with greater baseline impairment. The findings are exploratory and require confirmation in independent cohorts. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-21 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0050', 'SYNTH-ISRCTN-0000015', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000051', '51', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery: a longitudinal safety analysis', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2024', 'A multicentre investigation examined home strength and balance exercise against standard care in 215 adults with postoperative joint replacement recovery. Between-group estimates favoured the intervention for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-02-10 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0051', 'SYNTH-ISRCTN-0000015', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000052', '52', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery: a study of implementation fidelity', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Trials', '2025', 'This prospective study assessed home strength and balance exercise against standard care in 215 adults with postoperative joint replacement recovery. The observed difference was clinically interpretable for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-01-10 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0052', 'SYNTH-ISRCTN-0000015', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000053', '53', 'Patient-reported experience after home strength and balance exercise for postoperative joint replacement recovery: a comparison across recruitment settings', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMJ Open', '2025', 'This report examined patient-reported experience and quality of life after home strength and balance exercise for postoperative joint replacement recovery. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in functional mobility were accompanied by variable satisfaction with access and treatment workload. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-29 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0053', 'SYNTH-ISRCTN-0000015', 'Patient-reported experience after home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000054', '54', 'Implementing home strength and balance exercise in routine care for postoperative joint replacement recovery: an analysis of resource use', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Journal of Clinical Epidemiology', '2025', 'This implementation report describes delivery of home strength and balance exercise for people with postoperative joint replacement recovery across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside functional mobility. Adoption was feasible, although local staffing and infrastructure shaped delivery. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-02-17 09:00:00', '2026-08-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0054', 'SYNTH-ISRCTN-0000015', 'Implementing home strength and balance exercise in routine care for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000055', '55', 'Budget impact ofhome strength and balance exercise for postoperative joint replacement recovery: a report on treatment acceptability', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home strength and balance exercise for postoperative joint replacement recovery. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. Costs were separated into intervention delivery, primary care, hospital care, and medication use. Site-level differences were retained in the model rather than treated as measurement error.', '2025-01-18 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0055', 'SYNTH-ISRCTN-0000015', 'Health-service costs associated with home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000056', '56', 'Longer-term outcomes following home strength and balance exercise in postoperative joint replacement recovery: a pragmatic registry analysis', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2026', 'This follow-up examined participants with postoperative joint replacement recovery after the initial evaluation of home strength and balance exercise. At six to twelve months, the direction of change in functional mobility was assessed alongside treatment persistence, healthcare use, and late adverse events. The analysis suggests durable benefit for some participants but remains vulnerable to loss to follow-up. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-02-06 09:00:00', '2026-08-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0056', 'SYNTH-ISRCTN-0000015', 'Longer-term outcomes following home strength and balance exercise in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000057', '57', 'Registered Protocol For The Planned Evaluation for personalised dietary counselling in hypertension: a study of care access and outcomes', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'BMJ Open', '2023', 'investigators explored personalised dietary counselling for adults with hypertension. Participants will be recruited through primary-care and specialist clinics; the planned sample is 252 and systolic blood pressure is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-01-07 09:00:00', '2026-01-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0057', 'SYNTH-ISRCTN-0000016', 'Registered Protocol For The Planned Evaluation for personalised dietary counselling in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000058', '58', 'A pragmatic evaluation of personalised dietary counselling for hypertension: an analysis of longer-term use', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'Journal of Clinical Epidemiology', '2024', 'The trial team compared personalised dietary counselling against standard care in 252 adults with hypertension. Results were consistent with the prespecified hypothesis for systolic blood pressure, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-26 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0058', 'SYNTH-ISRCTN-0000016', 'A pragmatic evaluation of personalised dietary counselling for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000059', '59', 'Methods Paper Describing The Trial Framework for brief sleep restriction therapy in insomnia in older adults: a report on clinical decision-making', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Journal of Clinical Epidemiology', '2024', 'investigators explored brief sleep restriction therapy for adults with insomnia in older adults. Participants will be recruited using electronic records and clinician referral; the planned sample is 289 and sleep efficiency is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-14 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0059', 'SYNTH-ISRCTN-0000017', 'Methods Paper Describing The Trial Framework for brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000060', '60', 'Clinical outcomes after brief sleep restriction therapy for insomnia in older adults: a multisite patient follow-up', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'The Lancet Regional Health', '2025', 'Investigators explored brief sleep restriction therapy against standard care in 289 adults with insomnia in older adults. Results were consistent with the prespecified hypothesis for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-01-15 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0060', 'SYNTH-ISRCTN-0000017', 'Clinical outcomes after brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000061', '61', 'Patient-reported experience after brief sleep restriction therapy for insomnia in older adults: evidence from participating centres', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMC Health Services Research', '2025', 'This report examined patient-reported experience and quality of life after brief sleep restriction therapy for insomnia in older adults. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in sleep efficiency were accompanied by variable satisfaction with access and treatment workload. The study team documented variation in delivery intensity across participating sites.', '2025-02-03 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0061', 'SYNTH-ISRCTN-0000017', 'Patient-reported experience after brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000062', '62', 'Adverse events and treatment exposure during brief sleep restriction therapy for insomnia in older adults: a pragmatic service evaluation', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Trials', '2026', 'Safety data from the evaluation of brief sleep restriction therapy for insomnia in older adults were reviewed across 289 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-02-22 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0062', 'SYNTH-ISRCTN-0000017', 'Adverse events and treatment exposure during brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000063', '63', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome: findings from routine clinical practice', 'Arjun Mehta//Grace Kim//Peter Osei', 'The Lancet Regional Health', '2025', 'Investigators explored pacing and energy conservation coaching against standard care in 326 adults with post-viral fatigue syndrome. Between-group estimates favoured the intervention for physical function, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-01-23 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0063', 'SYNTH-ISRCTN-0000018', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000064', '64', 'Baseline characteristics of adults enrolled in an evaluation of home blood pressure monitoring: a longitudinal cohort analysis', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'BMC Health Services Research', '2024', 'This baseline report describes 363 adults enrolled to assess home blood pressure monitoring for hypertension. Participants were recruited at urban and regional clinical sites; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-02-11 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0064', 'SYNTH-ISRCTN-0000019', 'Baseline characteristics of adults enrolled in an evaluation of home blood pressure monitoring', 'English', 'Medidex Synthetic Press'),
(NULL, '2000065', '65', 'A pragmatic evaluation of home blood pressure monitoring for hypertension: a participant-level secondary analysis', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'Trials', '2025', 'This prospective study assessed home blood pressure monitoring against standard care in 363 adults with hypertension. The observed difference was clinically interpretable for glycaemic control, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The analysis also considered differences between hospital and community delivery settings.', '2025-01-11 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0065', 'SYNTH-ISRCTN-0000019', 'A pragmatic evaluation of home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000066', '66', 'Baseline characteristics of adults enrolled in an evaluation of home pulmonary rehabilitation: a community-based assessment', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'Trials', '2025', 'This baseline report describes 400 adults enrolled to assess home pulmonary rehabilitation for chronic obstructive pulmonary disease. Participants were recruited across community services and outpatient practices; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-31 09:00:00', '2026-05-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0066', 'SYNTH-ISRCTN-0000020', 'Baseline characteristics of adults enrolled in an evaluation of home pulmonary rehabilitation', 'English', 'Medidex Synthetic Press'),
(NULL, '2000067', '67', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease: a patient-centred outcomes report', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'BMJ Open', '2024', 'The trial team compared home pulmonary rehabilitation against standard care in 400 adults with chronic obstructive pulmonary disease. The observed difference was clinically interpretable for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-02-19 09:00:00', '2026-05-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0067', 'SYNTH-ISRCTN-0000020', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000068', '68', 'Registered Protocol For The Planned Evaluation for a graded activity programme in chronic low back pain: results from linked clinical records', 'Amara Williams//Diego Alvarez//Ines Pereira', 'BMJ Open', '2024', 'investigators explored a graded activity programme for adults with chronic low back pain. Participants will be recruited across community services and outpatient practices; the planned sample is 437 and pain-related function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-01-19 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0068', 'SYNTH-ISRCTN-0000021', 'Registered Protocol For The Planned Evaluation for a graded activity programme in chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000069', '69', 'Comparative effectiveness of a graded activity programme for chronic low back pain: a mixed-methods implementation report', 'Amara Williams//Diego Alvarez//Ines Pereira', 'Journal of Clinical Epidemiology', '2025', 'This prospective study assessed a graded activity programme against standard care in 437 adults with chronic low back pain. Between-group estimates favoured the intervention for pain-related function, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-02-07 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0069', 'SYNTH-ISRCTN-0000021', 'Comparative effectiveness of a graded activity programme for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000070', '70', 'Protocol And Statistical Analysis Plan for structured medication review in heart failure with preserved ejection fraction: a multisite effectiveness study', 'Noor Rahman//Ethan Cole//Maya Singh', 'Journal of Clinical Epidemiology', '2025', 'a multicentre investigation examined structured medication review for adults with heart failure with preserved ejection fraction. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 474 and symptom burden is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-01-08 09:00:00', '2026-07-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0070', 'SYNTH-ISRCTN-0000022', 'Protocol And Statistical Analysis Plan for structured medication review in heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000071', '71', 'Comparative effectiveness of structured medication review for heart failure with preserved ejection fraction: a prespecified analysis of outcomes', 'Noor Rahman//Ethan Cole//Maya Singh', 'The Lancet Regional Health', '2024', 'The trial team compared structured medication review against standard care in 474 adults with heart failure with preserved ejection fraction. The primary analysis indicated a modest improvement for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. Service capacity and local referral practices influenced the observed pattern of care.', '2025-01-27 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0071', 'SYNTH-ISRCTN-0000022', 'Comparative effectiveness of structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000072', '72', 'Protocol And Statistical Analysis Plan for guided behavioural activation in major depressive disorder: a health-system perspective', 'Aisha Grant//Victor Petrov//Clara Martin', 'The Lancet Regional Health', '2022', 'an outpatient research network tested guided behavioural activation for adults with major depressive disorder. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 91 and depressive symptom severity is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-02-15 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0072', 'SYNTH-ISRCTN-0000023', 'Protocol And Statistical Analysis Plan for guided behavioural activation in major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000073', '73', 'Comparative effectiveness of guided behavioural activation for major depressive disorder: a follow-up analysis of care pathways', 'Aisha Grant//Victor Petrov//Clara Martin', 'BMC Health Services Research', '2025', 'This prospective study assessed guided behavioural activation against standard care in 91 adults with major depressive disorder. Results were consistent with the prespecified hypothesis for depressive symptom severity, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-01-16 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0073', 'SYNTH-ISRCTN-0000023', 'Comparative effectiveness of guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000074', '74', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery: an outpatient outcomes study', 'Amina Okafor//Luis Martinez//Priya Nair', 'BMC Health Services Research', '2025', 'An outpatient research network tested home strength and balance exercise against standard care in 128 adults with postoperative joint replacement recovery. Results were consistent with the prespecified hypothesis for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-02-04 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0074', 'SYNTH-ISRCTN-0000024', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000075', '75', 'Implementing personalised dietary counselling in routine care for hypertension: a real-world assessment of delivery', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'Trials', '2025', 'This implementation report describes delivery of personalised dietary counselling for people with hypertension across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside systolic blood pressure. Adoption was feasible, although local staffing and infrastructure shaped delivery. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-23 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0075', 'SYNTH-ISRCTN-0000025', 'Implementing personalised dietary counselling in routine care for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000076', '76', 'Registered Protocol For The Planned Evaluation for brief sleep restriction therapy in insomnia in older adults: an analysis of treatment persistence', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'BMJ Open', '2025', 'this prospective study assessed brief sleep restriction therapy for adults with insomnia in older adults. Participants will be recruited through primary-care and specialist clinics; the planned sample is 202 and sleep efficiency is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-01-24 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0076', 'SYNTH-ISRCTN-0000026', 'Registered Protocol For The Planned Evaluation for brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000077', '77', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults: a report from regional services', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'Journal of Clinical Epidemiology', '2024', 'Researchers evaluated brief sleep restriction therapy against standard care in 202 adults with insomnia in older adults. Results were consistent with the prespecified hypothesis for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The study team documented variation in delivery intensity across participating sites.', '2025-02-12 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0077', 'SYNTH-ISRCTN-0000026', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000078', '78', 'Correction: Brief Sleep Restriction Therapy and sleep efficiency in insomnia in older adults: a clinical epidemiology analysis', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'The Lancet Regional Health', '2026', 'This notice corrects a nonclinical metadata error in an earlier report on brief sleep restriction therapy for insomnia in older adults. The participant population, intervention, comparator, analyses, and clinical conclusions are unchanged. The corrected record clarifies the outcome definition and preserves the original study context for evidence review. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-01-13 09:00:00', '2026-03-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0078', 'SYNTH-ISRCTN-0000026', 'Correction: Brief Sleep Restriction Therapy and sleep efficiency in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000079', '79', 'Baseline characteristics of adults enrolled in an evaluation of pacing and energy conservation coaching: an assessment of variation in response', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Journal of Clinical Epidemiology', '2023', 'This baseline report describes 239 adults enrolled to assess pacing and energy conservation coaching for post-viral fatigue syndrome. Participants were recruited across community services and outpatient practices; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-02-01 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0079', 'SYNTH-ISRCTN-0000027', 'Baseline characteristics of adults enrolled in an evaluation of pacing and energy conservation coaching', 'English', 'Medidex Synthetic Press'),
(NULL, '2000080', '80', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome: a service-user experience report', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2025', 'An outpatient research network tested pacing and energy conservation coaching against standard care in 239 adults with post-viral fatigue syndrome. The primary analysis indicated a modest improvement for physical function, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-02-20 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0080', 'SYNTH-ISRCTN-0000027', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000081', '81', 'Implementing pacing and energy conservation coaching in routine care for post-viral fatigue syndrome: a longitudinal safety analysis', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2025', 'This implementation report describes delivery of pacing and energy conservation coaching for people with post-viral fatigue syndrome across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside physical function. Adoption was feasible, although local staffing and infrastructure shaped delivery. The analysis also considered differences between hospital and community delivery settings.', '2025-01-20 09:00:00', '2026-04-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0081', 'SYNTH-ISRCTN-0000027', 'Implementing pacing and energy conservation coaching in routine care for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000082', '82', 'Patient-reported experience after pacing and energy conservation coaching for post-viral fatigue syndrome: a study of implementation fidelity', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Trials', '2025', 'This report examined patient-reported experience and quality of life after pacing and energy conservation coaching for post-viral fatigue syndrome. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in physical function were accompanied by variable satisfaction with access and treatment workload. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-02-09 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0082', 'SYNTH-ISRCTN-0000027', 'Patient-reported experience after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000083', '83', 'Implementing pacing and energy conservation coaching in routine care for post-viral fatigue syndrome: a comparison across recruitment settings', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMJ Open', '2025', 'This implementation report describes delivery of pacing and energy conservation coaching for people with post-viral fatigue syndrome across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside physical function. Adoption was feasible, although local staffing and infrastructure shaped delivery. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-01-09 09:00:00', '2026-04-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0083', 'SYNTH-ISRCTN-0000027', 'Implementing pacing and energy conservation coaching in routine care for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000084', '84', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome: an analysis of resource use', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Journal of Clinical Epidemiology', '2025', 'Researchers evaluated pacing and energy conservation coaching against standard care in 239 adults with post-viral fatigue syndrome. Between-group estimates favoured the intervention for physical function, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-01-28 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0084', 'SYNTH-ISRCTN-0000027', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000085', '85', 'Patient-reported experience after pacing and energy conservation coaching for post-viral fatigue syndrome: a report on treatment acceptability', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2025', 'This report examined patient-reported experience and quality of life after pacing and energy conservation coaching for post-viral fatigue syndrome. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in physical function were accompanied by variable satisfaction with access and treatment workload. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-02-16 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0085', 'SYNTH-ISRCTN-0000027', 'Patient-reported experience after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000086', '86', 'Health-system costs forpacing and energy conservation coaching for post-viral fatigue syndrome: a pragmatic registry analysis', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with pacing and energy conservation coaching for post-viral fatigue syndrome. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. The economic model varied staff time, service intensity, and the assumed duration of treatment benefit.', '2025-01-17 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0086', 'SYNTH-ISRCTN-0000027', 'Health-service costs associated with pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000087', '87', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome: a study of care access and outcomes', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Trials', '2024', 'Investigators explored pacing and energy conservation coaching against standard care in 239 adults with post-viral fatigue syndrome. Results were consistent with the prespecified hypothesis for physical function, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. Service capacity and local referral practices influenced the observed pattern of care.', '2025-02-05 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0087', 'SYNTH-ISRCTN-0000027', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000088', '88', 'Who benefits from pacing and energy conservation coaching? A subgroup analysis in post-viral fatigue syndrome: an analysis of longer-term use', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMJ Open', '2025', 'This analysis explored heterogeneity of response to pacing and energy conservation coaching in adults with post-viral fatigue syndrome. Improvement in physical function was observed across several prespecified strata, with the largest estimates among participants with greater baseline impairment. The findings are exploratory and require confirmation in independent cohorts. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-06 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0088', 'SYNTH-ISRCTN-0000027', 'Who benefits from pacing and energy conservation coaching? A subgroup analysis in post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000089', '89', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome: a report on clinical decision-making', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'Journal of Clinical Epidemiology', '2024', 'The trial team compared pacing and energy conservation coaching against standard care in 239 adults with post-viral fatigue syndrome. Results were consistent with the prespecified hypothesis for physical function, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-01-25 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0089', 'SYNTH-ISRCTN-0000027', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000090', '90', 'Adverse events and treatment exposure during pacing and energy conservation coaching for post-viral fatigue syndrome: a multisite patient follow-up', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'The Lancet Regional Health', '2026', 'Safety data from the evaluation of pacing and energy conservation coaching for post-viral fatigue syndrome were reviewed across 239 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-02-13 09:00:00', '2026-04-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0090', 'SYNTH-ISRCTN-0000027', 'Adverse events and treatment exposure during pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000091', '91', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension: evidence from participating centres', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'The Lancet Regional Health', '2023', 'researchers evaluated home blood pressure monitoring for adults with hypertension. Participants will be recruited through primary-care and specialist clinics; the planned sample is 276 and glycaemic control is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. Differences in adherence were more pronounced among participants recruited through community services.', '2025-01-14 09:00:00', '2026-05-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0091', 'SYNTH-ISRCTN-0000028', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000092', '92', 'Protocol And Statistical Analysis Plan for home pulmonary rehabilitation in chronic obstructive pulmonary disease: a pragmatic service evaluation', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMC Health Services Research', '2024', 'investigators explored home pulmonary rehabilitation for adults with chronic obstructive pulmonary disease. Participants will be recruited across community services and outpatient practices; the planned sample is 313 and exercise tolerance is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-02-02 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0092', 'SYNTH-ISRCTN-0000029', 'Protocol And Statistical Analysis Plan for home pulmonary rehabilitation in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000093', '93', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease: findings from routine clinical practice', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Trials', '2025', 'An outpatient research network tested home pulmonary rehabilitation against standard care in 313 adults with chronic obstructive pulmonary disease. The primary analysis indicated a modest improvement for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The study team documented variation in delivery intensity across participating sites.', '2025-02-21 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0093', 'SYNTH-ISRCTN-0000029', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000094', '94', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease: a longitudinal cohort analysis', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMJ Open', '2024', 'The trial team compared home pulmonary rehabilitation against standard care in 313 adults with chronic obstructive pulmonary disease. The primary analysis indicated a modest improvement for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-01-22 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0094', 'SYNTH-ISRCTN-0000029', 'A pragmatic evaluation of home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000095', '95', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease: a participant-level secondary analysis', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Journal of Clinical Epidemiology', '2025', 'Researchers evaluated home pulmonary rehabilitation against standard care in 313 adults with chronic obstructive pulmonary disease. The observed difference was clinically interpretable for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-02-10 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0095', 'SYNTH-ISRCTN-0000029', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000096', '96', 'Longer-term outcomes following home pulmonary rehabilitation in chronic obstructive pulmonary disease: a community-based assessment', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'The Lancet Regional Health', '2026', 'This follow-up examined participants with chronic obstructive pulmonary disease after the initial evaluation of home pulmonary rehabilitation. At six to twelve months, the direction of change in exercise tolerance was assessed alongside treatment persistence, healthcare use, and late adverse events. The analysis suggests durable benefit for some participants but remains vulnerable to loss to follow-up. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-01-10 09:00:00', '2026-06-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0096', 'SYNTH-ISRCTN-0000029', 'Longer-term outcomes following home pulmonary rehabilitation in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000097', '97', 'Baseline characteristics of adults enrolled in an evaluation of a graded activity programme: a patient-centred outcomes report', 'Arjun Mehta//Grace Kim//Peter Osei', 'Trials', '2023', 'This baseline report describes 350 adults enrolled to assess a graded activity programme for chronic low back pain. Participants were recruited across community services and outpatient practices; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The analysis also considered differences between hospital and community delivery settings.', '2025-01-30 09:00:00', '2026-07-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0097', 'SYNTH-ISRCTN-0000030', 'Baseline characteristics of adults enrolled in an evaluation of a graded activity programme', 'English', 'Medidex Synthetic Press'),
(NULL, '2000098', '98', 'Comparative effectiveness of a graded activity programme for chronic low back pain: results from linked clinical records', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMJ Open', '2024', 'This prospective study assessed a graded activity programme against standard care in 350 adults with chronic low back pain. Between-group estimates favoured the intervention for pain-related function, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-02-18 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0098', 'SYNTH-ISRCTN-0000030', 'Comparative effectiveness of a graded activity programme for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000099', '99', 'Protocol And Statistical Analysis Plan for structured medication review in heart failure with preserved ejection fraction: a mixed-methods implementation report', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'BMJ Open', '2022', 'an outpatient research network tested structured medication review for adults with heart failure with preserved ejection fraction. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 387 and symptom burden is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-01-18 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0099', 'SYNTH-ISRCTN-0000031', 'Protocol And Statistical Analysis Plan for structured medication review in heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000100', '100', 'A pragmatic evaluation of structured medication review for heart failure with preserved ejection fraction: a multisite effectiveness study', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'Journal of Clinical Epidemiology', '2025', 'The trial team compared structured medication review against standard care in 387 adults with heart failure with preserved ejection fraction. Between-group estimates favoured the intervention for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-02-06 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0100', 'SYNTH-ISRCTN-0000031', 'A pragmatic evaluation of structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000101', '101', 'Baseline characteristics of adults enrolled in an evaluation of guided behavioural activation: a prespecified analysis of outcomes', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'Journal of Clinical Epidemiology', '2025', 'This baseline report describes 424 adults enrolled to assess guided behavioural activation for major depressive disorder. Participants were recruited using electronic records and clinician referral; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-07 09:00:00', '2026-01-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0101', 'SYNTH-ISRCTN-0000032', 'Baseline characteristics of adults enrolled in an evaluation of guided behavioural activation', 'English', 'Medidex Synthetic Press'),
(NULL, '2000102', '102', 'Comparative effectiveness of guided behavioural activation for major depressive disorder: a health-system perspective', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'The Lancet Regional Health', '2024', 'This prospective study assessed guided behavioural activation against standard care in 424 adults with major depressive disorder. The intervention showed a small but measurable benefit for depressive symptom severity, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-01-26 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0102', 'SYNTH-ISRCTN-0000032', 'Comparative effectiveness of guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000103', '103', 'Prospective Study Protocol for home strength and balance exercise in postoperative joint replacement recovery: a follow-up analysis of care pathways', 'Amara Williams//Diego Alvarez//Ines Pereira', 'The Lancet Regional Health', '2024', 'researchers evaluated home strength and balance exercise for adults with postoperative joint replacement recovery. Participants will be recruited at urban and regional clinical sites; the planned sample is 461 and functional mobility is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. Service capacity and local referral practices influenced the observed pattern of care.', '2025-02-14 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0103', 'SYNTH-ISRCTN-0000033', 'Prospective Study Protocol for home strength and balance exercise in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000104', '104', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery: an outpatient outcomes study', 'Amara Williams//Diego Alvarez//Ines Pereira', 'BMC Health Services Research', '2025', 'Investigators explored home strength and balance exercise against standard care in 461 adults with postoperative joint replacement recovery. The observed difference was clinically interpretable for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-15 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0104', 'SYNTH-ISRCTN-0000033', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000105', '105', 'Prospective Study Protocol for personalised dietary counselling in hypertension: a real-world assessment of delivery', 'Noor Rahman//Ethan Cole//Maya Singh', 'BMC Health Services Research', '2025', 'investigators explored personalised dietary counselling for adults with hypertension. Participants will be recruited at urban and regional clinical sites; the planned sample is 498 and systolic blood pressure is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-02-03 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0105', 'SYNTH-ISRCTN-0000034', 'Prospective Study Protocol for personalised dietary counselling in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000106', '106', 'A pragmatic evaluation of personalised dietary counselling for hypertension: an analysis of treatment persistence', 'Noor Rahman//Ethan Cole//Maya Singh', 'Trials', '2024', 'Investigators explored personalised dietary counselling against standard care in 498 adults with hypertension. The intervention showed a small but measurable benefit for systolic blood pressure, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-02-22 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0106', 'SYNTH-ISRCTN-0000034', 'A pragmatic evaluation of personalised dietary counselling for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000107', '107', 'Design And Implementation Protocol for brief sleep restriction therapy in insomnia in older adults: a report from regional services', 'Aisha Grant//Victor Petrov//Clara Martin', 'Trials', '2022', 'investigators explored brief sleep restriction therapy for adults with insomnia in older adults. Participants will be recruited at urban and regional clinical sites; the planned sample is 115 and sleep efficiency is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. Differences in adherence were more pronounced among participants recruited through community services.', '2025-01-23 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0107', 'SYNTH-ISRCTN-0000035', 'Design And Implementation Protocol for brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000108', '108', 'Clinical outcomes after brief sleep restriction therapy for insomnia in older adults: a clinical epidemiology analysis', 'Aisha Grant//Victor Petrov//Clara Martin', 'BMJ Open', '2025', 'This prospective study assessed brief sleep restriction therapy against standard care in 115 adults with insomnia in older adults. The intervention showed a small but measurable benefit for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-02-11 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0108', 'SYNTH-ISRCTN-0000035', 'Clinical outcomes after brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000109', '109', 'Longer-term outcomes following brief sleep restriction therapy in insomnia in older adults: an assessment of variation in response', 'Aisha Grant//Victor Petrov//Clara Martin', 'Journal of Clinical Epidemiology', '2026', 'This follow-up examined participants with insomnia in older adults after the initial evaluation of brief sleep restriction therapy. At six to twelve months, the direction of change in sleep efficiency was assessed alongside treatment persistence, healthcare use, and late adverse events. The analysis suggests durable benefit for some participants but remains vulnerable to loss to follow-up. The study team documented variation in delivery intensity across participating sites.', '2025-01-12 09:00:00', '2026-04-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0109', 'SYNTH-ISRCTN-0000035', 'Longer-term outcomes following brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000110', '110', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome: a service-user experience report, report 110', 'Amina Okafor//Luis Martinez//Priya Nair', 'BMJ Open', '2025', 'Investigators explored pacing and energy conservation coaching against standard care in 152 adults with post-viral fatigue syndrome. The primary analysis indicated a modest improvement for physical function, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-01-31 09:00:00', '2026-05-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0110', 'SYNTH-ISRCTN-0000036', 'Clinical outcomes after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000111', '111', 'Clinical outcomes after home blood pressure monitoring for hypertension: a longitudinal safety analysis', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'Journal of Clinical Epidemiology', '2024', 'The trial team compared home blood pressure monitoring against standard care in 189 adults with hypertension. The intervention showed a small but measurable benefit for glycaemic control, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-02-19 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0111', 'SYNTH-ISRCTN-0000037', 'Clinical outcomes after home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000112', '112', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease: a study of implementation fidelity', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'The Lancet Regional Health', '2025', 'This prospective study assessed home pulmonary rehabilitation against standard care in 226 adults with chronic obstructive pulmonary disease. The observed difference was clinically interpretable for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-01-19 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0112', 'SYNTH-ISRCTN-0000038', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000113', '113', 'Implementing a graded activity programme in routine care for chronic low back pain: a comparison across recruitment settings', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMC Health Services Research', '2025', 'This implementation report describes delivery of a graded activity programme for people with chronic low back pain across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside pain-related function. Adoption was feasible, although local staffing and infrastructure shaped delivery. The analysis also considered differences between hospital and community delivery settings.', '2025-02-08 09:00:00', '2026-08-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0113', 'SYNTH-ISRCTN-0000039', 'Implementing a graded activity programme in routine care for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000114', '114', 'Baseline characteristics of adults enrolled in an evaluation of structured medication review: an analysis of resource use', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'Trials', '2024', 'This baseline report describes 300 adults enrolled to assess structured medication review for heart failure with preserved ejection fraction. Participants were recruited through primary-care and specialist clinics; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-08 09:00:00', '2026-01-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0114', 'SYNTH-ISRCTN-0000040', 'Baseline characteristics of adults enrolled in an evaluation of structured medication review', 'English', 'Medidex Synthetic Press'),
(NULL, '2000115', '115', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction: a report on treatment acceptability', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'BMJ Open', '2024', 'Researchers evaluated structured medication review against standard care in 300 adults with heart failure with preserved ejection fraction. The primary analysis indicated a modest improvement for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-01-27 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0115', 'SYNTH-ISRCTN-0000040', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000117', '117', 'Adverse events and treatment exposure during structured medication review for heart failure with preserved ejection fraction: a study of care access and outcomes', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'The Lancet Regional Health', '2025', 'Safety data from the evaluation of structured medication review for heart failure with preserved ejection fraction were reviewed across 300 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-16 09:00:00', '2026-01-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0117', 'SYNTH-ISRCTN-0000040', 'Adverse events and treatment exposure during structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000118', '118', 'Baseline characteristics of adults enrolled in an evaluation of guided behavioural activation: an analysis of longer-term use', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMJ Open', '2025', 'This baseline report describes 337 adults enrolled to assess guided behavioural activation for major depressive disorder. Participants were recruited through primary-care and specialist clinics; baseline severity, medication use, functional status, and social factors were recorded before treatment allocation. The cohort was broadly representative of the intended clinical population, although referral patterns may affect external validity. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-02-04 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0118', 'SYNTH-ISRCTN-0000041', 'Baseline characteristics of adults enrolled in an evaluation of guided behavioural activation', 'English', 'Medidex Synthetic Press'),
(NULL, '2000119', '119', 'Clinical outcomes after guided behavioural activation for major depressive disorder: a report on clinical decision-making', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Journal of Clinical Epidemiology', '2025', 'Researchers evaluated guided behavioural activation against standard care in 337 adults with major depressive disorder. The intervention showed a small but measurable benefit for depressive symptom severity, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Service capacity and local referral practices influenced the observed pattern of care.', '2025-02-23 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0119', 'SYNTH-ISRCTN-0000041', 'Clinical outcomes after guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000120', '120', 'Adverse events and treatment exposure during guided behavioural activation for major depressive disorder: a multisite patient follow-up', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'The Lancet Regional Health', '2026', 'Safety data from the evaluation of guided behavioural activation for major depressive disorder were reviewed across 337 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The analysis was designed to reflect the decisions faced by clinicians in routine practice.', '2025-01-24 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0120', 'SYNTH-ISRCTN-0000041', 'Adverse events and treatment exposure during guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000121', '121', 'Registered Protocol For The Planned Evaluation for home strength and balance exercise in postoperative joint replacement recovery: evidence from participating centres', 'Arjun Mehta//Grace Kim//Peter Osei', 'Journal of Clinical Epidemiology', '2025', 'the trial team compared home strength and balance exercise for adults with postoperative joint replacement recovery. Participants will be recruited using electronic records and clinician referral; the planned sample is 374 and functional mobility is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-02-12 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0121', 'SYNTH-ISRCTN-0000042', 'Registered Protocol For The Planned Evaluation for home strength and balance exercise in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000122', '122', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery: a pragmatic service evaluation', 'Arjun Mehta//Grace Kim//Peter Osei', 'The Lancet Regional Health', '2024', 'An outpatient research network tested home strength and balance exercise against standard care in 374 adults with postoperative joint replacement recovery. Between-group estimates favoured the intervention for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-13 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0122', 'SYNTH-ISRCTN-0000042', 'A pragmatic evaluation of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000123', '123', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery: findings from routine clinical practice', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMC Health Services Research', '2025', 'The trial team compared home strength and balance exercise against standard care in 374 adults with postoperative joint replacement recovery. The intervention showed a small but measurable benefit for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-01 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0123', 'SYNTH-ISRCTN-0000042', 'Comparative effectiveness of home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000124', '124', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery: a longitudinal cohort analysis', 'Arjun Mehta//Grace Kim//Peter Osei', 'Trials', '2025', 'This analysis explored heterogeneity of response to home strength and balance exercise in adults with postoperative joint replacement recovery. Improvement in functional mobility was observed across several prespecified strata, with the largest estimates among participants with greater baseline impairment. The findings are exploratory and require confirmation in independent cohorts. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-02-20 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0124', 'SYNTH-ISRCTN-0000042', 'Who benefits from home strength and balance exercise? A subgroup analysis in postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000125', '125', 'Adverse events and treatment exposure during home strength and balance exercise for postoperative joint replacement recovery: a participant-level secondary analysis', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMJ Open', '2025', 'Safety data from the evaluation of home strength and balance exercise for postoperative joint replacement recovery were reviewed across 374 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The study team documented variation in delivery intensity across participating sites.', '2025-01-21 09:00:00', '2026-03-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0125', 'SYNTH-ISRCTN-0000042', 'Adverse events and treatment exposure during home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000126', '126', 'Comparative effectiveness of personalised dietary counselling for hypertension: a community-based assessment', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'The Lancet Regional Health', '2024', 'This prospective study assessed personalised dietary counselling against standard care in 411 adults with hypertension. The intervention showed a small but measurable benefit for systolic blood pressure, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-02-09 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0126', 'SYNTH-ISRCTN-0000043', 'Comparative effectiveness of personalised dietary counselling for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000127', '127', 'Design And Implementation Protocol for brief sleep restriction therapy in insomnia in older adults: a patient-centred outcomes report', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'BMC Health Services Research', '2023', 'an outpatient research network tested brief sleep restriction therapy for adults with insomnia in older adults. Participants will be recruited within a pragmatic network of hospital and community providers; the planned sample is 448 and sleep efficiency is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-01-09 09:00:00', '2026-05-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0127', 'SYNTH-ISRCTN-0000044', 'Design And Implementation Protocol for brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000128', '128', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults: results from linked clinical records', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'Trials', '2024', 'Researchers evaluated brief sleep restriction therapy against standard care in 448 adults with insomnia in older adults. The primary analysis indicated a modest improvement for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-01-29 09:00:00', '2026-05-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0128', 'SYNTH-ISRCTN-0000044', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000130', '130', 'Methods Paper Describing The Trial Framework for pacing and energy conservation coaching in post-viral fatigue syndrome: a multisite effectiveness study', 'Amara Williams//Diego Alvarez//Ines Pereira', 'Trials', '2024', 'an outpatient research network tested pacing and energy conservation coaching for adults with post-viral fatigue syndrome. Participants will be recruited across community services and outpatient practices; the planned sample is 485 and physical function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-17 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0130', 'SYNTH-ISRCTN-0000045', 'Methods Paper Describing The Trial Framework for pacing and energy conservation coaching in post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000131', '131', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension: a prespecified analysis of outcomes', 'Noor Rahman//Ethan Cole//Maya Singh', 'BMJ Open', '2025', 'the trial team compared home blood pressure monitoring for adults with hypertension. Participants will be recruited using electronic records and clinician referral; the planned sample is 102 and glycaemic control is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-02-05 09:00:00', '2026-07-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0131', 'SYNTH-ISRCTN-0000046', 'Design And Implementation Protocol for home blood pressure monitoring in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000132', '132', 'A pragmatic evaluation of home blood pressure monitoring for hypertension: a health-system perspective', 'Noor Rahman//Ethan Cole//Maya Singh', 'Journal of Clinical Epidemiology', '2024', 'Researchers evaluated home blood pressure monitoring against standard care in 102 adults with hypertension. Between-group estimates favoured the intervention for glycaemic control, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-01-06 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0132', 'SYNTH-ISRCTN-0000046', 'A pragmatic evaluation of home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000133', '133', 'Secondary analysis of glycaemic control after home blood pressure monitoring for hypertension: a follow-up analysis of care pathways', 'Noor Rahman//Ethan Cole//Maya Singh', 'The Lancet Regional Health', '2025', 'A prespecified secondary analysis examined variation in glycaemic control after home blood pressure monitoring among adults with hypertension. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-25 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0133', 'SYNTH-ISRCTN-0000046', 'Secondary analysis of glycaemic control after home blood pressure monitoring for hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000134', '134', 'Protocol And Statistical Analysis Plan for home pulmonary rehabilitation in chronic obstructive pulmonary disease: an outpatient outcomes study', 'Aisha Grant//Victor Petrov//Clara Martin', 'Journal of Clinical Epidemiology', '2022', 'an outpatient research network tested home pulmonary rehabilitation for adults with chronic obstructive pulmonary disease. Participants will be recruited at urban and regional clinical sites; the planned sample is 139 and exercise tolerance is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-02-13 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0134', 'SYNTH-ISRCTN-0000047', 'Protocol And Statistical Analysis Plan for home pulmonary rehabilitation in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000135', '135', 'Comparative effectiveness of home pulmonary rehabilitation for chronic obstructive pulmonary disease: a real-world assessment of delivery', 'Aisha Grant//Victor Petrov//Clara Martin', 'The Lancet Regional Health', '2025', 'An outpatient research network tested home pulmonary rehabilitation against standard care in 139 adults with chronic obstructive pulmonary disease. The observed difference was clinically interpretable for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. Service capacity and local referral practices influenced the observed pattern of care.', '2025-01-14 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0135', 'SYNTH-ISRCTN-0000047', 'Comparative effectiveness of home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000136', '136', 'Secondary analysis of exercise tolerance after home pulmonary rehabilitation for chronic obstructive pulmonary disease: an analysis of treatment persistence', 'Aisha Grant//Victor Petrov//Clara Martin', 'BMC Health Services Research', '2026', 'A prespecified secondary analysis examined variation in exercise tolerance after home pulmonary rehabilitation among adults with chronic obstructive pulmonary disease. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. The analysis was designed to reflect the decisions faced by clinicians in routine practice. The authors described uncertainty around maintenance of the observed pattern beyond follow-up.', '2025-02-02 09:00:00', '2026-08-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0136', 'SYNTH-ISRCTN-0000047', 'Secondary analysis of exercise tolerance after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000137', '137', 'Implementing a graded activity programme in routine care for chronic low back pain: a report from regional services', 'Amina Okafor//Luis Martinez//Priya Nair', 'The Lancet Regional Health', '2025', 'This implementation report describes delivery of a graded activity programme for people with chronic low back pain across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside pain-related function. Adoption was feasible, although local staffing and infrastructure shaped delivery. A prespecified sensitivity analysis produced estimates in the same general direction. The report included a prespecified comparison of urban and regional recruitment settings.', '2025-02-21 09:00:00', '2026-01-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0137', 'SYNTH-ISRCTN-0000048', 'Implementing a graded activity programme in routine care for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000138', '138', 'Implementing structured medication review in routine care for heart failure with preserved ejection fraction: a clinical epidemiology analysis', 'Kwame Mensah//Sofia Rossi//Hannah Wilson', 'BMC Health Services Research', '2025', 'This implementation report describes delivery of structured medication review for people with heart failure with preserved ejection fraction across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside symptom burden. Adoption was feasible, although local staffing and infrastructure shaped delivery. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-22 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0138', 'SYNTH-ISRCTN-0000049', 'Implementing structured medication review in routine care for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000139', '139', 'Implementing guided behavioural activation in routine care for major depressive disorder: an assessment of variation in response', 'Mei Chen//Daniel Brooks//Fatima Haddad', 'Trials', '2025', 'This implementation report describes delivery of guided behavioural activation for people with major depressive disorder across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside depressive symptom severity. Adoption was feasible, although local staffing and infrastructure shaped delivery. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-10 09:00:00', '2026-03-15 00:00:00', '4', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0139', 'SYNTH-ISRCTN-0000050', 'Implementing guided behavioural activation in routine care for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000140', '140', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery: a service-user experience report', 'Tunde Adeyemi//Elena Novak//Rafael Silva', 'BMJ Open', '2024', 'The trial team compared home strength and balance exercise against standard care in 287 adults with postoperative joint replacement recovery. The observed difference was clinically interpretable for functional mobility, while treatment exposure and adverse events were broadly comparable between groups. Interpretation is limited by attrition and the pragmatic delivery setting. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-01-11 09:00:00', '2026-04-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0140', 'SYNTH-ISRCTN-0000051', 'Clinical outcomes after home strength and balance exercise for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
(NULL, '2000141', '141', 'Protocol And Statistical Analysis Plan for personalised dietary counselling in hypertension: a longitudinal safety analysis', 'Leila Ibrahim//Marcus Thompson//Keiko Yamamoto', 'Journal of Clinical Epidemiology', '2023', 'this prospective study assessed personalised dietary counselling for adults with hypertension. Participants will be recruited across community services and outpatient practices; the planned sample is 324 and systolic blood pressure is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. The study team documented variation in delivery intensity across participating sites.', '2025-01-30 09:00:00', '2026-05-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0141', 'SYNTH-ISRCTN-0000052', 'Protocol And Statistical Analysis Plan for personalised dietary counselling in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000142', '142', 'Registered Protocol For The Planned Evaluation for brief sleep restriction therapy in insomnia in older adults: a study of implementation fidelity', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'The Lancet Regional Health', '2024', 'a multicentre investigation examined brief sleep restriction therapy for adults with insomnia in older adults. Participants will be recruited using electronic records and clinician referral; the planned sample is 361 and sleep efficiency is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-02-18 09:00:00', '2026-06-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0142', 'SYNTH-ISRCTN-0000053', 'Registered Protocol For The Planned Evaluation for brief sleep restriction therapy in insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000143', '143', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults: a comparison across recruitment settings', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMC Health Services Research', '2025', 'The trial team compared brief sleep restriction therapy against standard care in 361 adults with insomnia in older adults. The primary analysis indicated a modest improvement for sleep efficiency, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-01-18 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0143', 'SYNTH-ISRCTN-0000053', 'Comparative effectiveness of brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000144', '144', 'Adverse events and treatment exposure during brief sleep restriction therapy for insomnia in older adults: an analysis of resource use', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Trials', '2026', 'Safety data from the evaluation of brief sleep restriction therapy for insomnia in older adults were reviewed across 361 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-02-07 09:00:00', '2026-06-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0144', 'SYNTH-ISRCTN-0000053', 'Adverse events and treatment exposure during brief sleep restriction therapy for insomnia in older adults', 'English', 'Medidex Synthetic Press'),
(NULL, '2000145', '145', 'Design And Implementation Protocol for pacing and energy conservation coaching in post-viral fatigue syndrome: a report on treatment acceptability', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMC Health Services Research', '2025', 'a multicentre investigation examined pacing and energy conservation coaching for adults with post-viral fatigue syndrome. Participants will be recruited through primary-care and specialist clinics; the planned sample is 398 and physical function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Interpretation is limited by attrition and the pragmatic delivery setting. The analysis also considered differences between hospital and community delivery settings.', '2025-01-07 09:00:00', '2026-07-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0145', 'SYNTH-ISRCTN-0000054', 'Design And Implementation Protocol for pacing and energy conservation coaching in post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000146', '146', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome: a pragmatic registry analysis', 'Arjun Mehta//Grace Kim//Peter Osei', 'Trials', '2024', 'An outpatient research network tested pacing and energy conservation coaching against standard care in 398 adults with post-viral fatigue syndrome. The observed difference was clinically interpretable for physical function, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Recruitment pathways and treatment fidelity were examined to support interpretation of the estimates.', '2025-01-26 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0146', 'SYNTH-ISRCTN-0000054', 'Comparative effectiveness of pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000147', '147', 'Secondary analysis of physical function after pacing and energy conservation coaching for post-viral fatigue syndrome: a study of care access and outcomes', 'Arjun Mehta//Grace Kim//Peter Osei', 'BMJ Open', '2025', 'A prespecified secondary analysis examined variation in physical function after pacing and energy conservation coaching among adults with post-viral fatigue syndrome. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. The report includes a sensitivity analysis using an alternative definition of the primary outcome.', '2025-02-15 09:00:00', '2026-07-15 00:00:00', '2', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0147', 'SYNTH-ISRCTN-0000054', 'Secondary analysis of physical function after pacing and energy conservation coaching for post-viral fatigue syndrome', 'English', 'Medidex Synthetic Press'),
(NULL, '2000148', '148', 'Prospective Study Protocol for home blood pressure monitoring in hypertension: an analysis of longer-term use', 'Marta Kowalski//Jonas Berg//Lucia Ferraro', 'Trials', '2022', 'this prospective study assessed home blood pressure monitoring for adults with hypertension. Participants will be recruited using electronic records and clinician referral; the planned sample is 435 and glycaemic control is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. Patient retention varied by site, with the largest losses occurring before the final assessment.', '2025-01-15 09:00:00', '2026-08-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0148', 'SYNTH-ISRCTN-0000055', 'Prospective Study Protocol for home blood pressure monitoring in hypertension', 'English', 'Medidex Synthetic Press'),
(NULL, '2000150', '150', 'Registered Protocol For The Planned Evaluation for home pulmonary rehabilitation in chronic obstructive pulmonary disease: a multisite patient follow-up', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'BMJ Open', '2023', 'an outpatient research network tested home pulmonary rehabilitation for adults with chronic obstructive pulmonary disease. Participants will be recruited through primary-care and specialist clinics; the planned sample is 472 and exercise tolerance is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. Generalisability may be reduced because participating sites had established research infrastructure. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-02-22 09:00:00', '2026-01-15 00:00:00', '1', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0150', 'SYNTH-ISRCTN-0000056', 'Registered Protocol For The Planned Evaluation for home pulmonary rehabilitation in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000151', '151', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease: evidence from participating centres', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'Journal of Clinical Epidemiology', '2024', 'The trial team compared home pulmonary rehabilitation against standard care in 472 adults with chronic obstructive pulmonary disease. Between-group estimates favoured the intervention for exercise tolerance, while treatment exposure and adverse events were broadly comparable between groups. Generalisability may be reduced because participating sites had established research infrastructure. Service capacity and local referral practices influenced the observed pattern of care.', '2025-01-23 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0151', 'SYNTH-ISRCTN-0000056', 'Clinical outcomes after home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000152', '152', 'An economic evaluation ofhome pulmonary rehabilitation for chronic obstructive pulmonary disease: a pragmatic service evaluation', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'The Lancet Regional Health', '2025', 'A within-trial economic evaluation estimated healthcare use and costs associated with home pulmonary rehabilitation for chronic obstructive pulmonary disease. Resource use, service contacts, medication changes, and quality-adjusted survival were compared with standard care. Results were sensitive to assumptions about intervention delivery and longer-term maintenance. The economic model varied staff time, service intensity, and the assumed duration of treatment benefit.', '2025-02-11 09:00:00', '2026-01-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0152', 'SYNTH-ISRCTN-0000056', 'Health-service costs associated with home pulmonary rehabilitation for chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000153', '153', 'Correction: Home Pulmonary Rehabilitation and exercise tolerance in chronic obstructive pulmonary disease: findings from routine clinical practice', 'Zainab Bello//Thomas Wright//Yuki Tanaka', 'BMC Health Services Research', '2026', 'This notice corrects a nonclinical metadata error in an earlier report on home pulmonary rehabilitation for chronic obstructive pulmonary disease. The participant population, intervention, comparator, analyses, and clinical conclusions are unchanged. The corrected record clarifies the outcome definition and preserves the original study context for evidence review. A prespecified sensitivity analysis produced estimates in the same general direction.', '2025-01-12 09:00:00', '2026-01-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0153', 'SYNTH-ISRCTN-0000056', 'Correction: Home Pulmonary Rehabilitation and exercise tolerance in chronic obstructive pulmonary disease', 'English', 'Medidex Synthetic Press'),
(NULL, '2000154', '154', 'Protocol And Statistical Analysis Plan for a graded activity programme in chronic low back pain: a longitudinal cohort analysis', 'Amara Williams//Diego Alvarez//Ines Pereira', 'Journal of Clinical Epidemiology', '2024', 'this prospective study assessed a graded activity programme for adults with chronic low back pain. Participants will be recruited at urban and regional clinical sites; the planned sample is 89 and pain-related function is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The study was not powered to detect uncommon adverse events. The report distinguishes protocol-defined outcomes from exploratory measures collected during follow-up.', '2025-01-31 09:00:00', '2026-02-15 00:00:00', '1', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0154', 'SYNTH-ISRCTN-0000057', 'Protocol And Statistical Analysis Plan for a graded activity programme in chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000155', '155', 'Clinical outcomes after a graded activity programme for chronic low back pain: a participant-level secondary analysis', 'Amara Williams//Diego Alvarez//Ines Pereira', 'The Lancet Regional Health', '2025', 'A multicentre investigation examined a graded activity programme against standard care in 89 adults with chronic low back pain. The primary analysis indicated a modest improvement for pain-related function, while treatment exposure and adverse events were broadly comparable between groups. The findings should be considered alongside short follow-up and incomplete adherence data. Differences in adherence were more pronounced among participants recruited through community services.', '2025-02-19 09:00:00', '2026-02-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0155', 'SYNTH-ISRCTN-0000057', 'Clinical outcomes after a graded activity programme for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000156', '156', 'Adverse events and treatment exposure during a graded activity programme for chronic low back pain: a community-based assessment', 'Amara Williams//Diego Alvarez//Ines Pereira', 'BMC Health Services Research', '2026', 'Safety data from the evaluation of a graded activity programme for chronic low back pain were reviewed across 89 participants. Most events were mild or unrelated to treatment; serious events were uncommon and balanced between groups. Exposure, discontinuation, and protocol deviations are reported to support interpretation of the clinical outcome findings. The investigators noted that the observed association should not be interpreted as proof of causation.', '2025-01-20 09:00:00', '2026-02-15 00:00:00', '4', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0156', 'SYNTH-ISRCTN-0000057', 'Adverse events and treatment exposure during a graded activity programme for chronic low back pain', 'English', 'Medidex Synthetic Press'),
(NULL, '2000157', '157', 'Design And Implementation Protocol for structured medication review in heart failure with preserved ejection fraction: a patient-centred outcomes report', 'Noor Rahman//Ethan Cole//Maya Singh', 'The Lancet Regional Health', '2025', 'researchers evaluated structured medication review for adults with heart failure with preserved ejection fraction. Participants will be recruited at urban and regional clinical sites; the planned sample is 126 and symptom burden is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The study team documented variation in delivery intensity across participating sites.', '2025-02-08 09:00:00', '2026-03-15 00:00:00', '1', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0157', 'SYNTH-ISRCTN-0000058', 'Design And Implementation Protocol for structured medication review in heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000158', '158', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction: results from linked clinical records', 'Noor Rahman//Ethan Cole//Maya Singh', 'BMC Health Services Research', '2024', 'A multicentre investigation examined structured medication review against standard care in 126 adults with heart failure with preserved ejection fraction. The observed difference was clinically interpretable for symptom burden, while treatment exposure and adverse events were broadly comparable between groups. The study was not powered to detect uncommon adverse events. Results were broadly stable after adjustment for age, baseline severity, and prior treatment.', '2025-01-08 09:00:00', '2026-03-15 00:00:00', '2', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0158', 'SYNTH-ISRCTN-0000058', 'Clinical outcomes after structured medication review for heart failure with preserved ejection fraction', 'English', 'Medidex Synthetic Press'),
(NULL, '2000159', '159', 'Methods Paper Describing The Trial Framework for guided behavioural activation in major depressive disorder: a mixed-methods implementation report', 'Aisha Grant//Victor Petrov//Clara Martin', 'BMC Health Services Research', '2022', 'researchers evaluated guided behavioural activation for adults with major depressive disorder. Participants will be recruited across community services and outpatient practices; the planned sample is 163 and depressive symptom severity is the principal endpoint. The protocol prespecifies safety, adherence, and quality-of-life measures and describes procedures for missing observations. The findings should be considered alongside short follow-up and incomplete adherence data. The report discusses how missing observations may affect interpretation of the final estimates.', '2025-01-28 09:00:00', '2026-04-15 00:00:00', '1', '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0159', 'SYNTH-ISRCTN-0000059', 'Methods Paper Describing The Trial Framework for guided behavioural activation in major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000160', '160', 'Implementing home strength and balance exercise in routine care for postoperative joint replacement recovery: a multisite effectiveness study', 'Amina Okafor//Luis Martinez//Priya Nair', 'Trials', '2025', 'This implementation report describes delivery of home strength and balance exercise for people with postoperative joint replacement recovery across routine services. Staff training, referral pathways, fidelity, reach, and participant engagement were monitored alongside functional mobility. Adoption was feasible, although local staffing and infrastructure shaped delivery. The findings are intended to inform evidence synthesis rather than replace confirmatory trials.', '2025-02-16 09:00:00', '2026-05-15 00:00:00', '4', '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0160', 'SYNTH-ISRCTN-0000060', 'Implementing home strength and balance exercise in routine care for postoperative joint replacement recovery', 'English', 'Medidex Synthetic Press'),
