(NULL, '2000197', '197', 'Patient-reported experience after guided behavioural activation for major depressive disorder: a report from regional services', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'BMJ Open', '2025', 'This report examined patient-reported experience and quality of life after guided behavioural activation for major depressive disorder. Participants described changes in daily activity, confidence, symptom control, and care burden. Improvements in depressive symptom severity were accompanied by variable satisfaction with access and treatment workload. Results were interpreted alongside baseline severity, treatment exposure, and concurrent care.', '2025-01-12 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Prospective cohort study', '10.5555/medidex.synthetic.0197', 'SYNTH-ISRCTN-0000077', 'Patient-reported experience after guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
(NULL, '2000198', '198', 'Secondary analysis of depressive symptom severity after guided behavioural activation for major depressive disorder: a clinical epidemiology analysis', 'Nadia Hassan//Samuel Reed//Chloe Dubois', 'Journal of Clinical Epidemiology', '2026', 'A prespecified secondary analysis examined variation in depressive symptom severity after guided behavioural activation among adults with major depressive disorder. Effects were explored by baseline severity, age, adherence, and recruitment setting. The pattern was directionally consistent with the primary analysis, but subgroup estimates were imprecise. The investigators reported uncertainty intervals rather than relying on a single summary estimate.', '2025-01-31 09:00:00', '2026-06-15 00:00:00', '2', '1', 'Open-label pilot study', '10.5555/medidex.synthetic.0198', 'SYNTH-ISRCTN-0000077', 'Secondary analysis of depressive symptom severity after guided behavioural activation for major depressive disorder', 'English', 'Medidex Synthetic Press'),
