-- Keep the synthetic corpus consistently usable for RCT-focused workflows.
UPDATE "tblStudy"
SET "Comparison" = 'Control: ' || CASE MOD("tblStudy"."CRGStudyID", 4)
        WHEN 0 THEN 'Usual care'
        WHEN 1 THEN 'Placebo education'
        WHEN 2 THEN 'Wait-list care'
        ELSE 'Routine care'
    END || ' vs Intervention: ' || intervention_names.names
FROM (
        SELECT si."CRGStudyID",
           string_agg(CASE i."InterventionID"
               WHEN 3000001 THEN 'CBT'
               WHEN 3000002 THEN 'Strength and balance exercise'
               WHEN 3000003 THEN 'Inhaled anti-inflammatory'
               WHEN 3000004 THEN 'Pharmacist review'
               WHEN 3000005 THEN 'Telemonitoring coaching'
               WHEN 3000006 THEN 'Dietary counselling'
               WHEN 3000007 THEN 'Mindfulness sessions'
               WHEN 3000008 THEN 'Educational material'
               ELSE i."InterventionDescription"
           END, ' + ' ORDER BY i."InterventionID") AS names
        FROM "tblStudyIntervention" si
        JOIN "tblIntervention" i ON i."InterventionID" = si."InterventionID"
        GROUP BY si."CRGStudyID"
) AS intervention_names
WHERE "tblStudy"."CRGStudyID" = intervention_names."CRGStudyID";

DELETE FROM "tblStudyDesign"
WHERE "DesignID" <> 3300001;

INSERT INTO "tblStudyDesign" ("CRGStudyID", "DesignID")
SELECT "CRGStudyID", 3300001
FROM "tblStudy"
ON CONFLICT DO NOTHING;

UPDATE "tblReport" r
SET "StudyDesign" = 'Parallel-group randomized controlled trial',
    "Abstract" = r."Abstract" || ' This report is from a parallel-group randomized controlled trial comparing Control: ' || CASE MOD(intervention_names."CRGStudyID", 4)
        WHEN 0 THEN 'usual care'
        WHEN 1 THEN 'placebo education'
        WHEN 2 THEN 'wait-list care'
        ELSE 'routine care'
    END || ' vs Intervention: ' || intervention_names.names || '.'
FROM (
        SELECT sr."CRGReportID",
           sr."CRGStudyID",
           string_agg(CASE i."InterventionID"
               WHEN 3000001 THEN 'CBT'
               WHEN 3000002 THEN 'strength and balance exercise'
               WHEN 3000003 THEN 'inhaled anti-inflammatory therapy'
               WHEN 3000004 THEN 'pharmacist medication review'
               WHEN 3000005 THEN 'telemonitoring coaching'
               WHEN 3000006 THEN 'dietary counselling'
               WHEN 3000007 THEN 'mindfulness sessions'
               WHEN 3000008 THEN 'educational material'
               ELSE i."InterventionDescription"
           END, ' + ' ORDER BY i."InterventionID") AS names
        FROM "tblStudyReport" sr
        JOIN "tblStudyIntervention" si ON si."CRGStudyID" = sr."CRGStudyID"
        JOIN "tblIntervention" i ON i."InterventionID" = si."InterventionID"
    GROUP BY sr."CRGReportID", sr."CRGStudyID"
) AS intervention_names
WHERE r."CRGReportID" = intervention_names."CRGReportID"
    AND r."Abstract" NOT LIKE '%This report is from a parallel-group randomized controlled trial%';

UPDATE "tblReport"
SET "Title" = CASE MOD("CRGReportID", 6)
    WHEN 0 THEN 'Primary results from ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
    WHEN 1 THEN 'Comparative effectiveness of ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
    WHEN 2 THEN 'Treatment effects of ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
    WHEN 3 THEN 'Randomized trial of ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
    WHEN 4 THEN 'Efficacy and safety of ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
    ELSE 'Outcomes following ' || substring("Title" FROM length('Clinical outcomes after ') + 1)
END
WHERE "Title" LIKE 'Clinical outcomes after %';

-- Registration identifiers are shared by reports from the same study, but are
-- intentionally absent from some secondary and follow-up records.
UPDATE "tblReport" r
SET "TrialRegistrationID" = CASE
    WHEN MOD(r."CRGReportID", 4) IN (0, 1) THEN s."TrialRegistrationID"
    ELSE NULL
END
FROM "tblStudyReport" sr
JOIN "tblStudy" s ON s."CRGStudyID" = sr."CRGStudyID"
WHERE r."CRGReportID" = sr."CRGReportID";

SELECT setval(
    pg_get_serial_sequence('"tblReport"', 'CRGReportID'),
    COALESCE(MAX("CRGReportID"), 1),
    COUNT(*) > 0
)
FROM "tblReport";

COMMIT;
